draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // mango
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // leaf
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 + 60 + 10 * Math.cos(t), H/2 - 60, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // stick figure enjoying mango
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 + 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 70);
  ctx.lineTo(W/2 - 100, H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 90);
  ctx.lineTo(W/2 - 80, H/2 + 110);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 90);
  ctx.lineTo(W/2 - 120, H/2 + 110);
  ctx.stroke();

  ctx.restore();
}
